export interface SiteImage {
  src: string;
  srcSet?: string;
  width: number;
  height: number;
  alt: string;
}

const pair = (
  small: string,
  large: string,
  width: number,
  height: number,
  alt: string,
): SiteImage => ({
  src: large,
  srcSet: `${small} 800w, ${large} ${width}w`,
  width,
  height,
  alt,
});

